import streamlit as st

# إعدادات الصفحة لتشبه واجهة البرنامج
st.set_page_config(page_title="توب 10 مع صالح", layout="wide")

# تصميم CSS لتحسين المظهر وجعله باللون الأخضر مثل الصورة
st.markdown("""
    <style>
    .main { background-color: #1e3d2f; }
    .answer-box {
        background-color: #4CAF50;
        color: white;
        padding: 20px;
        border-radius: 10px;
        text-align: center;
        font-size: 20px;
        font-weight: bold;
        margin: 10px;
        min-height: 80px;
        display: flex;
        align-items: center;
        justify-content: center;
    }
    .hidden-box {
        background-color: #2e5a43;
        border: 2px dashed #ffffff55;
        color: transparent;
    }
    .title-text { color: white; text-align: center; font-size: 40px; }
    </style>
    """, unsafe_allow_html=True)

st.markdown("<h1 class='title-text'>🏆 توب 10 مع صالح 🏆</h1>", unsafe_allow_html=True)
st.markdown("<h3 style='text-align: center; color: white;'>أعلى 10 دول في العالم من حيث عدد السكان</h3>", unsafe_allow_html=True)

# بيانات اللعبة (يمكنك تغييرها لكل جولة)
top_10_data = {
    1: {"name": "الهند", "info": "1.47 مليار"},
    2: {"name": "الصين", "info": "1.41 مليار"},
    3: {"name": "الولايات المتحدة", "info": "349 مليون"},
    4: {"name": "إندونيسيا", "info": "287 مليون"},
    5: {"name": "باكستان", "info": "259 مليون"},
    6: {"name": "نيجيريا", "info": "230 مليون"},
    7: {"name": "البرازيل", "info": "213 مليون"},
    8: {"name": "بنجلاديش", "info": "177 مليون"},
    9: {"name": "روسيا", "info": "143 مليون"},
    10: {"name": "إثيوبيا", "info": "138 مليون"},
}

# إدارة حالة اللعبة (النقاط والإجابات الظاهرة)
if 'revealed' not in st.session_state:
    st.session_state.revealed = []
if 'score_team_a' not in st.session_state:
    st.session_state.score_team_a = 0
if 'score_team_b' not in st.session_state:
    st.session_state.score_team_b = 0

# توزيع الإجابات على صفين (مثل الصورة)
col1, col2 = st.columns(2)

for i in range(1, 11):
    target_col = col2 if i <= 5 else col1
    with target_col:
        if i in st.session_state.revealed:
            st.markdown(f"<div class='answer-box'>{i} - {top_10_data[i]['name']} ({top_10_data[i]['info']})</div>", unsafe_allow_html=True)
        else:
            if st.button(f"كشف المركز {i}", key=f"btn_{i}"):
                st.session_state.revealed.append(i)
                st.rerun()

st.markdown("---")

# منطقة النقاط والفرق
footer_col1, footer_col2, footer_col3 = st.columns([2, 1, 2])

with footer_col1:
    team_a_name = st.text_input("اسم الفريق الأول", "الفريق أ")
    st.write(f"## {st.session_state.score_team_a}")
    if st.button(f"إضافة نقاط لـ {team_a_name}"):
        # إضافة نقاط آخر إجابة تم كشفها
        if st.session_state.revealed:
            st.session_state.score_team_a += st.session_state.revealed[-1]
            st.rerun()

with footer_col3:
    team_b_name = st.text_input("اسم الفريق الثاني", "الفريق ب")
    st.write(f"## {st.session_state.score_team_b}")
    if st.button(f"إضافة نقاط لـ {team_b_name}"):
        if st.session_state.revealed:
            st.session_state.score_team_b += st.session_state.revealed[-1]
            st.rerun()

with footer_col2:
    if st.button("إعادة ضبط اللعبة"):
        st.session_state.revealed = []
        st.session_state.score_team_a = 0
        st.session_state.score_team_b = 0
        st.rerun()


